def _native_reference_leaf(value: dict, source_sha256: str):
    """Validate a complete serialized native leaf without fetching or selecting it."""
    from GSE.curation.external_sources.wiktionary import (
        WiktionaryDefinition,
        _native_reference_links,
        _native_reference_record,
    )

    if not isinstance(value, dict) or set(value) != {field.name for field in fields(WiktionaryDefinition)}:
        raise ValueError("INVALID_NATIVE_REFERENCE_LEAF_FIELDS")
    _require_json(value)
    for key in ("entry_id", "lemma", "word", "pos", "native_id", "record_sha256", "source_sha256", "identity_scheme"):
        _require_string(value[key], "INVALID_NATIVE_REFERENCE_LEAF_IDENTITY")
    if (
        not isinstance(value["senseid_path"], list)
        or any(not isinstance(part, str) for part in value["senseid_path"])
        or not isinstance(value["native_sense"], dict)
        or not isinstance(value["record_context"], dict)
        or value["record_context"].get("lang") != "English"
        or value["record_context"].get("lang_code") != "en"
    ):
        raise ValueError("INVALID_NATIVE_REFERENCE_LEAF_CONTENT")
    native_fields = dict(value)
    native_fields["senseid_path"] = tuple(value["senseid_path"])
    entry = WiktionaryDefinition(**native_fields)
    _native_reference_links(entry)
    if _native_reference_record(entry, source_sha256) != value:
        raise ValueError("INVALID_NATIVE_REFERENCE_LEAF_CONTENT")
    return entry


def _native_reference_observation_fields(packet: dict) -> dict:
    """Validate packet consistency; snapshot authenticity belongs to source replay."""
    from GSE.curation.external_sources.wiktionary import _lookup_form, _native_reference_links

    required = {
        "format",
        "code",
        "source_entry",
        "relation",
        "link",
        "target_word",
        "target_lookup",
        "target_entries",
        "other_pos_entries",
        "source_sha256",
    }
    if not isinstance(packet, dict) or set(packet) != required:
        raise ValueError("INVALID_NATIVE_REFERENCE_PACKET_FIELDS")
    _require_json(packet)
    if current_id(packet["format"]) != "GSE.wiktionary-definition-reference/1":
        raise ValueError("INVALID_NATIVE_REFERENCE_PACKET_FORMAT")
    sha = packet["source_sha256"]
    if not isinstance(sha, str) or len(sha) != 64 or any(char not in "0123456789abcdef" for char in sha):
        raise ValueError("INVALID_NATIVE_REFERENCE_SOURCE_HASH")
    original = _native_reference_leaf(packet["source_entry"], sha)
    if not any(
        packet["relation"] == relation and packet["link"] == link
        for relation, link in _native_reference_links(original)
    ):
        raise ValueError("NATIVE_REFERENCE_LINK_NOT_IN_SOURCE")
    word = packet["link"]["word"]
    if packet["target_word"] != word or packet["target_lookup"] != _lookup_form(word):
        raise ValueError("NATIVE_REFERENCE_TARGET_WORD_MISMATCH")
    matching, other = [], []
    for key, result in (("target_entries", matching), ("other_pos_entries", other)):
        records = packet[key]
        if not isinstance(records, list):
            raise ValueError("INVALID_NATIVE_REFERENCE_TARGET_LIST")
        seen = set()
        for record in records:
            target = _native_reference_leaf(record, sha)
            location = (target.source_line, target.sense_index)
            if location in seen:
                raise ValueError("DUPLICATE_NATIVE_REFERENCE_TARGET_LOCATION")
            seen.add(location)
            if target.lemma != packet["target_lookup"]:
                raise ValueError("NATIVE_REFERENCE_TARGET_IDENTITY_MISMATCH")
            if (target.pos == original.pos) != (key == "target_entries"):
                raise ValueError("NATIVE_REFERENCE_TARGET_POS_MISMATCH")
            result.append(target)
        if records != sorted(
            records, key=lambda record: (record["entry_id"], record["source_line"], record["sense_index"])
        ):
            raise ValueError("NONDETERMINISTIC_NATIVE_REFERENCE_TARGET_ORDER")
    if len({target.entry_id for target in matching}) > 1:
        code = "AMBIGUOUS_TARGET_SENSES"
    elif matching:
        code = (
            "TARGET_IS_REFERENCE"
            if any(_native_reference_links(target) for target in matching)
            else "TARGET_DEFINITIONS_AVAILABLE"
        )

    {
        "definition_states",
        "primitive_values",
        "sentence_primitive_values",
        "source_observations",
        "sqlite_sequence",
    }
)
_STREAMS = {
    "native_observations": "SELECT record_id,entry_id,source,family,scope,payload FROM source_observations ORDER BY record_id",
    "definitions": "SELECT d.entry_id,l.lemma,l.pos,l.sense_id,l.gloss,l.source "
    "FROM definition_states d JOIN lexemes l ON l.id=d.lexeme_id ORDER BY d.entry_id",
}


def _fingerprint(path):
    with path.open("rb") as stream:
        return file_digest(stream, "sha256").hexdigest()


def _identity(path):
    stat = path.stat()
    return {"device": stat.st_dev, "inode": stat.st_ino, "logical_bytes": stat.st_size, "mtime_ns": stat.st_mtime_ns}


def _stream(connection, query, parameters=()):
    digest, count = sha256(), 0
    for row in connection.execute(query, parameters):
        payload = json.dumps(row, ensure_ascii=False, separators=(",", ":")).encode()
        digest.update(len(payload).to_bytes(8, "big"))
        digest.update(payload)
        count += 1
    return {"rows": count, "sha256": digest.hexdigest()}


def retire_snapshot(
    source,
    active,
    previous,
    *,
    expected_sha256,
    previous_sha256,
    archive_path,
    receipt_path,
    handle_check,
    new_context_ids=(),
):
    """Preserve complete native streams and every unique non-derived row.

    ``new_context_ids`` names separately audited context additions in the active
    successor. A record absent from the retired snapshot may be omitted from the
    witness comparison only when explicitly named here. No old source may vanish.
    The caller supplies the established local-file handle instrument; its named
    positive result is required before unlinking. Active and rollback are protected.
    """
    source, active, previous = (Path(path).absolute() for path in (source, active, previous))
    archive_path, receipt_path = Path(archive_path), Path(receipt_path)
    if source.is_symlink() or source.resolve() in {active.resolve(), previous.resolve()}:
        raise ValueError("RETIREMENT_PROTECTS_ACTIVE_AND_ROLLBACK")
    if resolve_lexicon_path().resolve() != active.resolve() or _fingerprint(active) != expected_sha256:
        raise ValueError("RETIREMENT_ACTIVE_WITNESS_CHANGED")
    if previous.is_symlink() or not previous.is_file() or _fingerprint(previous) != previous_sha256:
        raise ValueError("RETIREMENT_ROLLBACK_MISSING_OR_CHANGED")
    if receipt_path.exists():
        receipt = json.loads(receipt_path.read_text())
        if (
            source.exists()
            or receipt["path"] != str(source)
            or receipt["witness_sha256"] != expected_sha256
            or receipt["witness"] != str(active)
            or receipt["previous_sha256"] != previous_sha256
        ):
            raise ValueError("RETIREMENT_RECEIPT_IDENTITY_CHANGED")
        if _fingerprint(Path(receipt["audit_archive"])) != receipt["archive_sha256"]:
            raise ValueError("RETIREMENT_ARCHIVE_CHANGED")
        return receipt
    intent_path = receipt_path.with_suffix(".intent.json")
    if not source.exists():
        if not intent_path.exists():
            raise ValueError("RETIREMENT_ABSENT_WITHOUT_VERIFIED_INTENT")
        intent = json.loads(intent_path.read_text())
        if (
            intent.get("code") != "SNAPSHOT_RETIREMENT_READY"
            or intent.get("path") != str(source)
            or intent.get("witness_sha256") != expected_sha256
            or intent.get("previous_sha256") != previous_sha256
            or intent.get("audit_archive") != str(archive_path)
            or _fingerprint(archive_path) != intent.get("archive_sha256")
        ):
            raise ValueError("RETIREMENT_INTERRUPTED_INTENT_MISMATCH")
        result = {**intent, "code": "SOURCE_AND_UNIQUE_AUDITS_PRESERVED_SNAPSHOT_RETIRED"}
        record(receipt_path, result)
        return result
    if (
        not isinstance(new_context_ids, tuple)
        or len(set(new_context_ids)) != len(new_context_ids)
        or any(type(identity) is not str or not identity for identity in new_context_ids)
    ):
        raise ValueError("RETIREMENT_INVALID_NEW_CONTEXT_IDENTITIES")
    before, source_hash = _identity(source), _fingerprint(source)
    checks, tables = {}, {}
    with (
        closing(sqlite3.connect(source.resolve(strict=True).as_uri() + "?mode=ro", uri=True)) as old,
        closing(sqlite3.connect(active.resolve(strict=True).as_uri() + "?mode=ro", uri=True)) as witness,
    ):
        old.execute("PRAGMA query_only=ON")
        witness.execute("PRAGMA query_only=ON")
        missing = tuple(
            identity
            for identity in new_context_ids
            if not old.execute("SELECT 1 FROM source_observations WHERE record_id=?", (identity,)).fetchone()
        )
        for name, query in _STREAMS.items():
            target, parameters = query, ()
            if name == "native_observations" and missing:
                target = query.replace(
                    " ORDER BY record_id",
                    " WHERE record_id NOT IN (" + ",".join("?" for _ in missing) + ") ORDER BY record_id",
                )
                parameters = missing
            observed = _stream(old, query)
            if observed != _stream(witness, target, parameters):
                raise ValueError("RETIREMENT_SOURCE_STREAM_MISMATCH:" + name)
            checks[name] = observed
        old.execute("ATTACH DATABASE ? AS retained", (active.resolve().as_uri() + "?mode=ro",))
        for (name,) in old.execute("SELECT name FROM main.sqlite_master WHERE type='table' ORDER BY name").fetchall():
            if name in _DERIVED:
                continue
            table = '"' + name.replace('"', '""') + '"'
            columns = [row[1] for row in old.execute("PRAGMA main.table_info(" + table + ")")]
            if columns != [row[1] for row in old.execute("PRAGMA retained.table_info(" + table + ")")]:
                raise ValueError("RETIREMENT_SCHEMA_MISMATCH:" + name)
            fields = ",".join('"' + column.replace('"', '""') + '"' for column in columns)
            rows = old.execute(
                "SELECT " + fields + " FROM main." + table + " EXCEPT SELECT " + fields + " FROM retained." + table
            ).fetchall()
            if rows:
                tables[name] = {"columns": columns, "rows": rows}
    document = {
        "format": "GSE.checkpoint-audit-delta/1",
        "source": str(source),
        "source_sha256": source_hash,
        "witness": str(active),
        "witness_sha256": expected_sha256,
        "source_identity": before,
        "source_data_checks": checks,
        "excluded_new_context_ids_from_witness_only": list(missing),
        "tables": tables,
        "derived_or_verified_tables": sorted(_DERIVED),
    }
    encoded = json.dumps(document, sort_keys=True, ensure_ascii=False).encode()
    if archive_path.exists():
        if gzip.decompress(archive_path.read_bytes()) != encoded:
            raise ValueError("RETIREMENT_EXISTING_ARCHIVE_DIFFERS")
    else:
        with archive_path.open("xb") as stream:
            stream.write(gzip.compress(encoded, mtime=0))
            stream.flush()
            os.fsync(stream.fileno())
    if json.loads(gzip.decompress(archive_path.read_bytes())) != json.loads(encoded):
        raise ValueError("RETIREMENT_ARCHIVE_ROUNDTRIP_FAILED")
    handles = handle_check(source)
    if not isinstance(handles, dict) or handles.get("code") != "NO_OPEN_LOCAL_FILE_MATCHES":
        raise ValueError("RETIREMENT_NO_OPEN_HANDLES_NOT_ESTABLISHED")
    if _identity(source) != before or _fingerprint(source) != source_hash:
        raise ValueError("RETIREMENT_SOURCE_CHANGED")
    if any(Path(str(source) + suffix).exists() for suffix in ("-wal", "-shm", "-journal")):
        raise ValueError("RETIREMENT_HAS_SIDECAR")
    if resolve_lexicon_path().resolve() != active.resolve() or _fingerprint(active) != expected_sha256:
        raise ValueError("RETIREMENT_ACTIVE_WITNESS_CHANGED")
    if _fingerprint(previous) != previous_sha256:
        raise ValueError("RETIREMENT_ROLLBACK_MISSING_OR_CHANGED")
    result = {
        "code": "SOURCE_AND_UNIQUE_AUDITS_PRESERVED_SNAPSHOT_RETIRED",
        "path": str(source),
        "sha256": source_hash,
        "identity": before,
        "witness": str(active),
        "witness_sha256": expected_sha256,
        "previous_sha256": previous_sha256,
        "audit_archive": str(archive_path),
        "archive_sha256": _fingerprint(archive_path),
        "unique_audit_rows": {name: len(value["rows"]) for name, value in tables.items()},

        or not record["convention_id"].strip()
        or type(approval) is not dict
        or set(approval) != {"actor", "code", "question", "answer", "date"}
        or approval["actor"] != "Rohan"
        or approval["code"] != "APPROVED"
        or any(type(approval[k]) is not str or not approval[k].strip() for k in ("question", "answer", "date"))
    ):
        raise ValueError("EXPLICIT_FOUNDER_CONVENTION_APPROVAL_REQUIRED")
    left = candidate.get("premises") or ([candidate["antecedent"]] if candidate["antecedent"] else [])
    for pair in [record["consequent"], *(record["premises"] if type(record["premises"]) is list else [None])]:
        if (
            type(pair) is not list
            or len(pair) != 2
            or type(pair[0]) is not str
            or type(pair[1]) is not int
            or pair[1] not in (-1, 0, 1)
        ):
            raise ValueError("INVALID_CONVENTION_COORDINATES")
    if (
        record["premises"] != json.loads(json.dumps(left))
        or record["consequent"] != list(candidate["consequent"])
        or record["guards"] != json.loads(json.dumps(candidate["relation"]["guards"]))
        or candidate["warrant"]["kind"] != "APPROVED_GSE_CONVENTION"
    ):
        raise ValueError("CONVENTION_SCOPE_OR_WARRANT_MISMATCH")
    return "FOUNDER_APPROVED_CONVENTION_MODEL_AUDITS_DIAGNOSTIC"


class _AuditReplay:
    def __init__(self, records):
        self.records, self.index = records, 0

    @property
    def identity(self):
        if self.index >= len(self.records):
            raise ValueError("ADMISSION_AUDIT_EXHAUSTED")
        return self.records[self.index]["transport_identity"]

    def __call__(self, payload, schema):
        record = self.records[self.index]
        if _request_id(payload) != record["request_id"] or schema != record["schema"]:
            raise ValueError("ADMISSION_AUDIT_REQUEST_MISMATCH")
        self.index += 1
        return record["raw_output"]


def admit_records(raw, saved, review):
    """Return a pinned additive migration manifest; write no database or file."""
    from .reviewed_patterns import _relation, run_workflow_input

    required = {"rule_id", "review_id", "reviewer", "decision", "rationale", "source_refs", "warrant_sha256"}
    convention = type(review) is dict and review.get("decision") == CONVENTION_DECISION
    if type(review) is not dict or set(review) != required | ({"convention"} if convention else set()):
        raise ValueError("INVALID_RULE_ADMISSION_REVIEW")
    if review["decision"] not in ("APPROVE_DEFINITIONAL_RULE", CONVENTION_DECISION):
        raise ValueError("RULE_ADMISSION_NOT_APPROVED")
    if any(type(review[k]) is not str or not review[k].strip() for k in required - {"source_refs"}):
        raise ValueError("INVALID_RULE_ADMISSION_REVIEW")
    if (
        type(review["source_refs"]) is not list
        or not review["source_refs"]
        or any(type(v) is not str or not v.strip() for v in review["source_refs"])
    ):
        raise ValueError("RULE_ADMISSION_SOURCE_REQUIRED")
    if type(saved) is not dict or saved.get("input_sha256") != _request_id(raw):
        raise ValueError("RULE_ADMISSION_INPUT_MISMATCH")
    records = [a for c in saved["candidates"] for a in c["audits"] if a.get("model_calls") == 1]
    replay_transport = _AuditReplay(records)
    replay = run_workflow_input(raw, replay_transport, max_calls=saved["max_model_calls"])
    if replay_transport.index != len(records) or _request_id(replay) != _request_id(saved):
        raise ValueError("RULE_ADMISSION_AUDIT_REPLAY_MISMATCH")
    matches = [c for c in replay["candidates"] if c["relation"]["rule_id"] == review["rule_id"]]
    if len(matches) != 1:
        raise ValueError("RULE_ADMISSION_CANDIDATE_NOT_IDENTIFIED")
    candidate = matches[0]
    if (
        candidate["proposal_kind"] != "GUARDED_WARRANTED_PROPOSAL"
        or not candidate["warrant"]
        or candidate["warrant_sha256"] != review["warrant_sha256"]
    ):
        raise ValueError("RULE_ADMISSION_WARRANT_REQUIRED")
    if not candidate["discovery"] or any(r["code"] != "OBSERVED_AGREEMENT" for r in candidate["discovery"]):
        raise ValueError("RULE_ADMISSION_DISCOVERY_INCOMPLETE")
    if (
        not candidate["audits"]
        or any(
            r["code"] not in {"MODEL_AGREEMENT", "MODEL_COUNTEREXAMPLE", "MODEL_ABSTAINED"}
            if convention
            else r["code"] != "MODEL_AGREEMENT"
            for r in candidate["audits"]
        )
        or any(r["code"] != "STAGED_ONLY" for r in candidate["staging"])
    ):
        raise ValueError("RULE_ADMISSION_AUDIT_INCOMPLETE")
    authority = (
        _convention_authority(review["convention"], candidate)
        if convention
        else "SOURCE_BACKED_EXPLICIT_REVIEW_NOT_MODEL_GOLD"
    )
    relation = replace(_relation(json.loads(json.dumps(candidate["relation"]))), approved=True)
    if convention:
        relation = replace(
            relation,
            authority="foundational",
            provenance=(
                *relation.provenance,
                f"convention:{review['convention']['convention_id']}:{digest(review['convention'])}",

or current_id(revision["format"]) not in {FORMAT, RESERVATION_FORMAT}
or any(type(revision[key]) is not list for key in ("admissions", "retirements", "exceptions"))
or "reservations" in revision

                    != _canonical(identity_form(receipt["schema"]))
                    or assertion.value not in request.allowed_values
                ):
                    raise ValueError("MODEL_REQUEST_MISMATCH")
                after = resolve_dictionary(
                    BANKS,
                    prefix + (assertion,),
                    request_relations,
                    request_context,
                    evidence_banks=evidence_banks,
                    domain_restrictions=domain_restrictions,
                )
                if after.code == "CONFLICT":
                    raise ValueError("MODEL_ACCEPTED_CONTRADICTION")
                previous_exceptions = {
                    rule_id
                    for record in before.trace
                    if record["kind"] == "CONDITIONAL_EXCEPTION"
                    for rule_id in record["rule_ids"]
                }
                if any(
                    record["kind"] == "CONDITIONAL_EXCEPTION" and set(record["rule_ids"]) - previous_exceptions
                    for record in after.trace
                ):
                    raise ValueError("MODEL_ADDED_CONDITIONAL_EXCEPTION")
                if any(after.assignments.get(bank) != value for bank, value in before.assignments.items()):
                    raise ValueError("MODEL_CHANGED_KNOWN_ASSIGNMENT")
                remaining_models.remove(receipt)
            else:
                if model_started:
                    raise ValueError("MODEL_BEFORE_SYMBOLIC_EVIDENCE")
                validate_assertion_competence(assertion)
                observation = native.get((assertion.source, assertion.record_id))
                if (
                    observation is None
                    or observation.entry_id != entry_id
                    or observation.family != assertion.family
                    or observation.scope != "lexical"
                ):
                    raise ValueError("ASSERTION_PROVENANCE_MISMATCH")
                if assertion.source == "wiktionary":
                    from .evidence import wiktionary_definition_projection

                    row = conn.execute(
                        "SELECT payload FROM source_observations WHERE record_id=?", (assertion.record_id,)
                    ).fetchone()
                    features = _read_json(row[0])["features"] if row is not None else {}
                    projected = wiktionary_definition_projection(definition, features)
                    if projected.get(assertion.bank) != assertion.value:
                        genus = "PERSON" if assertion.bank == "SOMEONE" else "ANATOMY"
                        raise ValueError(f"WIKTIONARY_{genus}_PROJECTION_WITNESS_MISMATCH")
                if assertion.source == "gse_closed_class" and assertion.bank in {"I", "YOU"}:
                    from GSE.curation.external_sources.gse_closed_class import GSEClosedClassParser

                    row = conn.execute(
                        "SELECT payload FROM source_observations WHERE record_id=?", (assertion.record_id,)
                    ).fetchone()
                    features = _read_json(row[0])["features"] if row is not None else {}
                    if (
                        features.get("entry_id") != entry_id
                        or features.get("lemma") != definition.lemma
                        or features.get("definition") != definition.definition
                        or GSEClosedClassParser().reference_projection_for_observation(features).get(assertion.bank)
                        != assertion.value
                    ):
                        raise ValueError("CLOSED_CLASS_REFERENCE_PROJECTION_WITNESS_MISMATCH")
        prefix += (assertion,)
    if any(remaining_anchors.values()) or remaining_models:
        raise ValueError("UNCONSUMED_ASSERTION_AUTHORITY")


def _unresolved_integrity(conn, mismatch):
    counts = Counter()
    total = 0
    for row in conn.execute("SELECT ordinal,code,payload FROM unresolved_sources ORDER BY ordinal"):
        try:
            if type(row["ordinal"]) is not int or row["ordinal"] != total:
                raise ValueError("INVALID_DIAGNOSTIC_ORDINAL")
            record = _read_json(row["payload"])
            if not isinstance(record, dict) or not _identity(record.get("code")) or record["code"] != row["code"]:
                raise ValueError("DIAGNOSTIC_CODE_MISMATCH")
            counts[record["code"]] += 1
        except (TypeError, ValueError) as error:
            mismatch(None, "MALFORMED_SOURCE_DIAGNOSTIC", ordinal=row["ordinal"], reason=str(error))
        total += 1
    expected = {"table": "unresolved_sources", "records": total, "outcomes": dict(counts)}
    if _canonical(identity_form(_optional_metadata(conn, "unresolved_sources", None))) != _canonical(
        identity_form(expected)
    ):
        mismatch(None, "SOURCE_DIAGNOSTIC_METADATA_MISMATCH")


def _candidate_summary(raw, rule_id):
    required = {
        "relation",
        "antecedent",
        "consequent",
        "by_family",
        "admission",
        "propagation_scope",
        "evidence_counts",
    }
    if not isinstance(raw, dict) or set(raw) != required:
        raise ValueError("INVALID_CANDIDATE_SUMMARY_FIELDS")
    relation = _relations([raw["relation"]])[0]
    if (
        relation.rule_id != rule_id
        or relation.approved is not False
        or relation.authority != "conditional"
        or relation.guards
    ):
        raise ValueError("INVALID_CANDIDATE_AUTHORITY")
    if raw["admission"] != "UNAPPROVED_CANDIDATE" or raw["propagation_scope"] != "LOCAL_ARC_CONSISTENCY":
        raise ValueError("INVALID_CANDIDATE_ADMISSION")
    for key in ("antecedent", "consequent"):
        literal = raw[key]
        if (
            not isinstance(literal, list)
            or len(literal) != 2
            or literal[0] not in BANKS
            or type(literal[1]) is not int
            or literal[1] not in TERNARY
        ):
            raise ValueError("INVALID_CANDIDATE_LITERAL")
    (left, a), (right, b) = raw["antecedent"], raw["consequent"]
    identity = hashlib.sha256(json.dumps([left, a, right, b], separators=(",", ":")).encode()).hexdigest()[:20]
    rows = tuple((x, y) for x in sorted(TERNARY) for y in sorted(TERNARY) if x != a or y == b)
    if relation.rule_id != f"candidate:{identity}" or relation.banks != (left, right) or relation.allowed_rows != rows:
        raise ValueError("CANDIDATE_RELATION_MISMATCH")
    counts = raw["evidence_counts"]
    if (
        not isinstance(counts, dict)
        or set(counts) != set(_CANDIDATE_CATEGORIES)
        or any(type(value) is not int or value < 0 for value in counts.values())
    ):
        raise ValueError("INVALID_CANDIDATE_COUNTS")
    if not isinstance(raw["by_family"], dict):
        raise ValueError("INVALID_CANDIDATE_FAMILIES")
    allowed = {*_CANDIDATE_CATEGORIES, "eligible", "antecedent_unknown", "antecedent_other"} - {"ineligible"}
    for family, values in raw["by_family"].items():
        if not _identity(family) or not isinstance(values, dict):
            raise ValueError("INVALID_CANDIDATE_FAMILY_COUNTS")
        for key, value in values.items():
            if key.removeprefix("weighted_") not in allowed or type(value) not in (int, float) or value < 0:
                raise ValueError("INVALID_CANDIDATE_FAMILY_COUNTS")
            if not key.startswith("weighted_") and type(value) is not int:
                raise ValueError("INVALID_CANDIDATE_FAMILY_COUNTS")
            if key.startswith("weighted_"):
                _candidate_weight(value)
    return relation


def _candidate_weight(value):
    try:
        valid = type(value) in (int, float) and value >= 0 and math.isfinite(value)
    except OverflowError:
        valid = False
    if not valid:
        raise ValueError("INVALID_CANDIDATE_WEIGHT")


def _candidate_receipt(record, category, summary, native, assertions_for):
    if category == "ineligible":
        observations = [dict(record)]
        if observations[0].pop("code", None) != "NOT_SOURCE_LEXICAL_EVIDENCE":
            raise ValueError("INVALID_INELIGIBLE_REASON")
    else:
        required = {
            "entry_id",
            "source",
            "family",
            "weight",
            "code",
            "antecedent_values",
            "consequent_values",
            "observations",
        }
        if not isinstance(record, dict) or set(record) != required or not isinstance(record["observations"], list):
            raise ValueError("INVALID_CANDIDATE_RECEIPT_FIELDS")
        _candidate_weight(record["weight"])
        observations = record["observations"]
    cross_source = (
        category != "ineligible"
        and record["source"] == f"definition:{record['entry_id']}"
        and record["family"] == "cross-source"
    )
    values = defaultdict(set)
    provenance = set()
    for raw in observations:
        observation = BankObservation(**raw)
        if observation.bank not in BANKS:
            raise ValueError("UNKNOWN_CANDIDATE_BANK")
        if observation.value is None:
            raise ValueError("CANDIDATE_EVIDENCE_REQUIRES_STORED_ASSERTION")
        reference = native.get((observation.source, observation.record_id))
        assertion = Assertion(
            observation.bank, observation.value, observation.source, observation.record_id, observation.family
        )
        if (
            reference is None
            or reference.entry_id != observation.entry_id
            or reference.family != observation.family
            or reference.scope != observation.scope
            or assertion not in assertions_for(observation.entry_id)
        ):
            raise ValueError("CANDIDATE_EVIDENCE_PROVENANCE_MISMATCH")
        origin = (
            "model"
            if observation.source.startswith("model:") or observation.family == "model"
            else "derived"
            if observation.source.startswith(("rule:", "derived:")) or observation.family == "derived"
            else "source"
        )
        if observation.origin != origin:
            raise ValueError("CANDIDATE_ORIGIN_MISMATCH")
        if category == "ineligible":
            if observation.origin == "source" and observation.scope == "lexical":
                raise ValueError("ELIGIBLE_EVIDENCE_MARKED_INELIGIBLE")
        else:
            if (
                observation.origin != "source"
                or observation.scope != "lexical"
                or any(
                    getattr(observation, key) != record[key]
                    for key in (("entry_id",) if cross_source else ("entry_id", "source", "family"))
                )
                or observation.bank not in (summary["antecedent"][0], summary["consequent"][0])
            ):
                raise ValueError("INVALID_CANDIDATE_GROUP")
            values[observation.bank].add(observation.value)
            provenance.add(f"{observation.source}:{observation.record_id}")
    if category == "ineligible":
        return set()
    if cross_source:
        expected = set()
        for assertion in assertions_for(record["entry_id"]):
            reference = native.get((assertion.source, assertion.record_id))
            if (
                assertion.bank in (summary["antecedent"][0], summary["consequent"][0])
                and reference is not None
                and reference.entry_id == record["entry_id"]
                and reference.family == assertion.family
                and reference.scope == "lexical"
                and not assertion.source.startswith(("model:", "rule:", "derived:"))
                and assertion.family not in {"model", "derived"}
            ):
                expected.add(
                    BankObservation(
                        record["entry_id"],
                        assertion.bank,
                        assertion.value,
                        assertion.source,
                        assertion.record_id,
                        assertion.family,
                    )
                )
        if {BankObservation(**raw) for raw in observations} != expected:
            raise ValueError("CROSS_SOURCE_CANDIDATE_INCOMPLETE_EVIDENCE")
    (left, a), (right, b) = summary["antecedent"], summary["consequent"]
    left_values, right_values = values[left], values[right]
    if _canonical(identity_form(record["antecedent_values"])) != _canonical(
        identity_form(sorted(left_values))
    ) or _canonical(identity_form(record["consequent_values"])) != _canonical(identity_form(sorted(right_values))):
        raise ValueError("CANDIDATE_DOMAIN_RECEIPT_MISMATCH")
    if len(left_values) > 1:
        expected = ("conflicting", "ANTECEDENT_CONFLICT")
    elif left_values != {a}:
        raise ValueError("CANDIDATE_ANTECEDENT_NOT_ELIGIBLE")
    elif len(right_values) > 1:
        expected = ("conflicting", "CONSEQUENT_CONFLICT")
    elif not right_values:
        expected = ("unknown", "CONSEQUENT_UNOBSERVED")
    elif b in right_values:
        expected = ("support", "OBSERVED_AGREEMENT")
    else:
        expected = ("counterexamples", "OBSERVED_COUNTEREXAMPLE")
    if expected != (category, record["code"]):
        raise ValueError("CANDIDATE_CATEGORY_MISMATCH")
    return provenance if category == "support" else set()


def _candidates_integrity(conn, native, mismatch):
    @lru_cache(maxsize=512)
    def assertions_for(entry_id):
        return frozenset(
            _assertions(
                conn.execute("SELECT ordinal,payload FROM builder_assertions WHERE entry_id=?", (entry_id,)).fetchall()
            )
        )

    for row in conn.execute(
        "SELECT e.rule_id,e.category,e.ordinal FROM candidate_evidence e LEFT JOIN candidate_relations r ON r.rule_id=e.rule_id WHERE r.rule_id IS NULL"
    ):
        mismatch(None, "ORPHAN_CANDIDATE_EVIDENCE", rule_id=row[0], category=row[1], ordinal=row[2])
    seen = set()
    total = 0
    for row in conn.execute("SELECT rule_id,summary FROM candidate_relations ORDER BY rule_id"):
        rule_id = row["rule_id"]
        total += 1
        try:
            if rule_id in seen:
                raise ValueError("DUPLICATE_CANDIDATE_RULE")
            seen.add(rule_id)
            summary = _read_json(row["summary"])
            relation = _candidate_summary(summary, rule_id)
            counts, families, weighted = Counter(), Counter(), Counter()
            support_provenance = set()
            groups = set()
            for evidence in conn.execute(
                "SELECT category,ordinal,payload FROM candidate_evidence WHERE rule_id=? ORDER BY category,ordinal",
                (rule_id,),
            ):
                category = evidence["category"]
                if (
                    category not in _CANDIDATE_CATEGORIES
                    or type(evidence["ordinal"]) is not int
                    or evidence["ordinal"] != counts[category]
                ):
                    raise ValueError("INVALID_CANDIDATE_EVIDENCE_ORDINAL")
                receipt = _read_json(evidence["payload"])
                support_provenance.update(_candidate_receipt(receipt, category, summary, native, assertions_for))
                counts[category] += 1
                if category != "ineligible":
                    group = (receipt["entry_id"], receipt["source"], receipt["family"])
                    if group in groups:
                        raise ValueError("DUPLICATE_CANDIDATE_EVIDENCE_GROUP")
                    groups.add(group)
                    evidence_families = (
                        {item["family"] for item in receipt["observations"]}
                        if receipt["source"] == f"definition:{receipt['entry_id']}"
                        and receipt["family"] == "cross-source"
                        else {receipt["family"]}
                    )
                    for family in sorted(evidence_families):
                        for status in (
                            (category, "eligible") if category in {"support", "counterexamples"} else (category,)
                        ):
                            families[(family, status)] += 1
                            weighted[(family, status)] += receipt["weight"]
                            _candidate_weight(weighted[(family, status)])
            if {category: counts[category] for category in _CANDIDATE_CATEGORIES} != summary["evidence_counts"]:
                raise ValueError("CANDIDATE_EVIDENCE_COUNT_MISMATCH")
            if tuple(sorted(support_provenance)) != relation.provenance:
                raise ValueError("CANDIDATE_SUPPORT_PROVENANCE_MISMATCH")
            for family in set(summary["by_family"]) | {key[0] for key in families}:
                saved = summary["by_family"].get(family, {})
                for status in (*_CANDIDATE_CATEGORIES[:-1], "eligible"):
                    if saved.get(status, 0) != families[(family, status)] or not math.isclose(
                        saved.get(f"weighted_{status}", 0), weighted[(family, status)], rel_tol=1e-12, abs_tol=1e-12
                    ):
                        raise ValueError("CANDIDATE_FAMILY_COUNT_MISMATCH")
        except (TypeError, ValueError, KeyError) as error:
            mismatch(None, "MALFORMED_CANDIDATE", rule_id=rule_id, reason=str(error))
    saved = _optional_metadata(conn, "candidate_relations", None)
    expected = {"table": "candidate_relations", "evidence_table": "candidate_evidence", "records": total}
    if (saved is not None or total) and _canonical(identity_form(saved)) != _canonical(identity_form(expected)):
        mismatch(None, "CANDIDATE_METADATA_MISMATCH")


def _catalog_foundation(links, anchors, models, evidence, restriction_evidence, native):
    """Recover linked native records without conflating their authority with anchors/models."""
    assertions_by_entry, restrictions_by_entry = {}, {}
    for entry_id in {entry for entries in links.values() for entry in entries}:
        remaining_anchors = Counter(anchors.get(entry_id, ()))
        remaining_models = Counter(Assertion(**record["assertion"]) for record in models.get(entry_id, ()))
        assertions = []
        for assertion in _assertions(evidence.get(entry_id, [])):
            if remaining_anchors[assertion]:
                remaining_anchors[assertion] -= 1
            elif remaining_models[assertion]:
                remaining_models[assertion] -= 1
            else:
                validate_assertion_competence(assertion)
                observation = native.get((assertion.source, assertion.record_id))
                if (
                    observation is None
                    or observation.entry_id != entry_id
                    or observation.family != assertion.family
                    or observation.scope != "lexical"
                ):
                    raise ValueError("CATALOG_NATIVE_PROVENANCE_MISMATCH")
                assertions.append(assertion)
        if any(remaining_anchors.values()) or any(remaining_models.values()):
            raise ValueError("UNCONSUMED_CATALOG_ASSERTION_AUTHORITY")
        restrictions = _domain_restrictions(restriction_evidence.get(entry_id, []))
        _restriction_provenance(entry_id, restrictions, native)
        assertions_by_entry[entry_id] = tuple(assertions)
        restrictions_by_entry[entry_id] = restrictions
    return assertions_by_entry, restrictions_by_entry


def _native_catalog(
    anchors,
    relations,
    lexemes,
    links,
    models,
    evidence,
    restriction_evidence,
    native,
    bank_relevance,
    *,
    conn=None,
    legacy_duration=False,
):
    from .catalog import catalog_report
    from .foundation import WORDNET_ANCESTRY_GUARD_PREFIXES

    definitions = tuple(Definition(row["sense_id"], row["lemma"], row["pos"], row["gloss"]) for row in lexemes.values())
    assertions, restrictions = _catalog_foundation(links, anchors, models, evidence, restriction_evidence, native)
    needs_context = any(
        key.startswith((*WORDNET_ANCESTRY_GUARD_PREFIXES, NATIVE_FRAME_PREFIX)) or key == "wordnet_native_lemma"
        for rule in relations
        for key, _ in rule.guards
    )
    if needs_context and conn is None:
        raise ValueError("CATALOG_SOURCE_CONTEXT_REQUIRED")
    observations = (
        {
            definition.entry_id: _context_observations(conn, definition.entry_id, relations, definition)
            for definition in definitions
            if definition.entry_id in assertions
        }
        if needs_context
        else {}
    )
    return catalog_report(
        anchors,
        definitions,
        relations,
        prime_entries=links,
        native_assertions=assertions,
        native_domain_restrictions=restrictions,
        evidence_banks={entry: tuple(sorted(bank_relevance.get(entry, ()))) for entry in assertions},
        observations_by_entry=observations,
        legacy_duration=legacy_duration,
    )


def _catalog_integrity(
    conn, anchors, relations, lexemes, mismatch, models, evidence, restriction_evidence, native, bank_relevance
):
    from .catalog import catalog_report

    saved = _optional_metadata(conn, "catalog", None)
    links = _optional_metadata(conn, "prime_entries", {})
    if saved is None:
        mismatch(None, "CATALOG_METADATA_MISSING")
        return "MISSING"
    try:
        if not isinstance(saved, dict):
            raise ValueError("INVALID_CATALOG_METADATA")
        legacy_duration = any(
            unit["unit_id"] == "nsm:v20:some-time" and unit["mapping"]["code"] == "MISSING" for unit in saved["units"]
        )
        if current_id(saved.get("format")) == "GSE.nsm-catalog-coverage/1":
            definitions = tuple(
                Definition(row["sense_id"], row["lemma"], row["pos"], row["gloss"]) for row in lexemes.values()
            )
            expected = catalog_report(
                anchors, definitions, relations, prime_entries=links, legacy_duration=legacy_duration
            )
        elif current_id(saved.get("format")) == "GSE.nsm-catalog-coverage/2":
            expected = _native_catalog(
                anchors,
                relations,
                lexemes,
                links,
                models,
                evidence,
                restriction_evidence,
                native,
                bank_relevance,
                conn=conn,
                legacy_duration=legacy_duration,
            )
        else:
            raise ValueError("UNSUPPORTED_CATALOG_FORMAT")
        for report in (saved, expected):
            for unit in report["units"]:
                for record in unit["definitions"]:
                    record["definition"].pop("source_ids", None)
        if _canonical(identity_form(saved)) != _canonical(identity_form(expected)):
            raise ValueError("CATALOG_REPLAY_MISMATCH")
    except (TypeError, ValueError, KeyError, AttributeError) as error:
        mismatch(None, "CATALOG_METADATA_MISMATCH", reason=str(error))
        return "MISMATCH"
    return "RECOMPUTED_EXCLUDING_UNPERSISTED_SOURCE_IDS"


