def fingerprint(path):
    with path.open("rb") as stream:
        return file_digest(stream, "sha256").hexdigest()


def file_state(path):
    value = path.stat()
    return {
        "device": value.st_dev,
        "inode": value.st_ino,
        "logical_bytes": value.st_size,
        "mtime_ns": value.st_mtime_ns,
    }


def available(path):
    try:
        return read(path)
    except FileNotFoundError, json.JSONDecodeError:
        return None


def record_status(path, value):
    """Atomically replace a latest-status report; checkpoints stay immutable."""
    if path.is_symlink():
        raise ValueError("ROUND_STATUS_MUST_NOT_BE_SYMLINK")
    payload = json.dumps(value, sort_keys=True, indent=2, allow_nan=False) + "\n"
    fd, name = tempfile.mkstemp(prefix="." + path.name + ".", dir=path.parent)
    temporary = Path(name)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as stream:
            stream.write(payload)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
    finally:
        temporary.unlink(missing_ok=True)


def no_open_handles(path):
    result = subprocess.run(["lsof", "-nP", "-f", "-Fpn", "--", str(path)], capture_output=True, text=True)
    if result.returncode != 1 or result.stdout:
        raise ValueError("CHECKPOINT_OPEN_HANDLE_CHECK_FAILED:" + str(path))
    warning = None
    if result.stderr:
        # Parse the complete machine diagnostic, including its current mount
        # identity. Neither a cached UUID nor suppressed warnings is evidence.
        diagnostic = re.fullmatch(
            r"lsof: WARNING: can't stat\(\) smbfs file system (?P<mount>/Volumes/\.timemachine/[^\n]+)\n"
            r'      Output information may be incomplete.\n      assuming "dev=(?P<device>[0-9a-fA-F]+)" from mount table\n',
            result.stderr,
        )
        if diagnostic is None:
            raise ValueError("CHECKPOINT_OPEN_HANDLE_CHECK_FAILED:" + str(path))
        mount = Path(diagnostic["mount"])
        device = int(diagnostic["device"], 16)
        if path.absolute().is_relative_to(mount) or path.stat().st_dev == device:
            raise ValueError("CHECKPOINT_ON_UNINSPECTED_NETWORK_FILESYSTEM")
        warning = {"code": "UNRELATED_INACCESSIBLE_SMB_MOUNT", "path": str(mount), "device": device}
    return {"code": "NO_OPEN_LOCAL_FILE_MATCHES", "stderr": result.stderr, "unrelated_mount": warning}


def validate_retirement(item, protected):
    path = Path(item["path"])
    if path.resolve() in protected or not path.resolve().is_relative_to(ROOT / "data/lexicon_builder"):
        raise ValueError("CHECKPOINT_PROTECTED_OR_OUTSIDE_PROJECT")
    for part in (path, *path.parents):
        if part.is_symlink():
            raise ValueError("CHECKPOINT_SYMLINK")
        if part == ROOT:
            break
    if any(Path(str(path) + suffix).exists() for suffix in ("-wal", "-shm", "-journal")):
        raise ValueError("CHECKPOINT_HAS_LIVE_SIDECAR")
    if file_state(path) != {key: item[key] for key in ("device", "inode", "logical_bytes", "mtime_ns")}:
        raise ValueError("CHECKPOINT_IDENTITY_CHANGED")
    if fingerprint(path) != item["sha256"]:
        raise ValueError("CHECKPOINT_CONTENT_CHANGED")
    archive = Path(item["audit_delta"])
    if sha256(archive.read_bytes()).hexdigest() != item["audit_delta_sha256"]:
        raise ValueError("CHECKPOINT_ARCHIVE_CHANGED")
    document = json.loads(gzip.decompress(archive.read_bytes()))
    if (
        document["source_sha256"] != item["sha256"]
        or fingerprint(Path(document["witness"])) != document["witness_sha256"]
    ):
        raise ValueError("CHECKPOINT_ARCHIVE_WITNESS_CHANGED")
    item["open_file_check"] = no_open_handles(path)


